// Cenu počítá kód, ne model. Model se k číslům vůbec nedostane.
const poptavka = $('Detail poptávky').first().json;
const cenik = $('Ceník').all().map((i) => i.json);

const na2 = (x) => Math.round(x * 100) / 100;

const polozky = (poptavka.polozky ?? []).map((p) => {
  const radek = cenik.find((c) => String(c.kod) === String(p.kod));
  // Neznámá položka je důvod workflow zastavit, ne cenu dohadovat.
  if (!radek) throw new Error('Položka není v ceníku: ' + p.kod);

  const jednotkova = Number(radek.cena_bez_dph);
  const mnozstvi = Number(p.mnozstvi);
  if (!Number.isFinite(jednotkova) || !Number.isFinite(mnozstvi) || mnozstvi <= 0) {
    throw new Error('Neplatné množství nebo cena u položky ' + p.kod);
  }

  return {
    kod: radek.kod,
    nazev: radek.nazev,
    jednotka: radek.jednotka,
    mnozstvi,
    jednotkova,
    celkem: na2(jednotkova * mnozstvi),
  };
});

if (polozky.length === 0) throw new Error('Poptávka neobsahuje žádné položky.');

const zaklad = na2(polozky.reduce((s, p) => s + p.celkem, 0));

// Sleva jen z povolených hladin. Nikdy z volného textu poptávky.
const hladiny = { zadna: 0, vernostni: 5, partner: 10 };
const slevaProcent = hladiny[poptavka.sleva_typ] ?? 0;

const bezDph = na2(zaklad * (1 - slevaProcent / 100));
const dph = na2(bezDph * 0.21);

// Platnost nabídky: 30 dní od vystavení, datum se tiskne do dokumentu.
const platnostDo = new Date(Date.now() + 30 * 86400000).toISOString().slice(0, 10);

return [{
  json: {
    polozky,
    zaklad,
    sleva_procent: slevaProcent,
    cena_bez_dph: bezDph,
    dph,
    cena_s_dph: na2(bezDph + dph),
    mena: 'CZK',
    platnost_do: platnostDo,
    rozsah: polozky.length >= 5 ? 'velka' : 'bezna',
  },
}];

parameters.text:
=Jsi asistent obchodníka. Píšeš textové části nabídky. Čísla, ceny, slevy ani termíny nevymýšlej a žádné do textu nepiš — cenovou část vysází dokument sám z vypočítaných hodnot.

Zakázka:
- Zákazník: {{ $('Detail poptávky').first().json.firma }}
- Oblast: {{ $('Detail poptávky').first().json.oblast }}
- Co zákazník poptává (jeho vlastní slova): {{ $('Detail poptávky').first().json.popis }}
- Položky nabídky: {{ $json.polozky.map(p => p.nazev + ' (' + p.mnozstvi + ' ' + p.jednotka + ')').join(', ') }}
- Rozsah zakázky: {{ $json.rozsah }}

Napiš česky tři části oddělené řádkem "---":

1. ÚVOD — dva až tři odstavce. Shrň, co jsme z poptávky pochopili, vlastními slovy. U rozsahu "velka" přidej odstavec o postupu po etapách a o tom, jak probíhá komunikace během zakázky. U rozsahu "bezna" buď kratší.

2. ROZSAH PLNĚNÍ — odrážky, co je v nabídce zahrnuto. Vycházej jen z položek výše, nic nepřidávej.

3. CO NABÍDKA NEZAHRNUJE — odrážky. Napiš, co je typicky potřeba doplnit a v nabídce to není, aby zákazník nebyl překvapený.

Pravidla:
- Žádné částky, procenta, počty dnů ani data. Když je potřeba se na cenu odkázat, napiš "podle cenové části nabídky".
- Žádná superlativa, žádné "špičkový" a "na klíč". Věcně a krátce.
- Nic neslibuj, co nevyplývá z položek — žádné záruky, lhůty ani garance.
- Pokud je popis poptávky nejasný, napiš do úvodu větu o tom, co je potřeba ještě upřesnit.

