// Číselná řada a verze. Původní nabídka se nikdy nepřepisuje.
const detail = $('Detail poptávky').first().json;
const cena = $('Výpočet ceny').first().json;
const texty = $json.text ?? $json.output ?? '';

const verze = Number(detail.pocet_nabidek ?? 0) + 1;
const rok = new Date().getFullYear();
const cislo = 'NAB-' + rok + '-' + String(detail.id).padStart(5, '0') + '-v' + verze;

// Hrubá kontrola, že model nepřinesl vlastní čísla. Když v textu najdeme
// částku, která není v našem výpočtu, nabídku radši označíme k ruční kontrole.
const povolene = new Set([
  String(cena.zaklad),
  String(cena.cena_bez_dph),
  String(cena.dph),
  String(cena.cena_s_dph),
  String(cena.sleva_procent),
]);
const cisla = String(texty).match(/\d+[\s\u00a0]?\d*[,.]?\d*/g) ?? [];
const podezrela = cisla
  .map((c) => c.replace(/[\s\u00a0]/g, '').replace(',', '.'))
  .filter((c) => Number(c) >= 100 && !povolene.has(c));

return [{
  json: {
    ...cena,
    texty,
    cislo_nabidky: cislo,
    verze,
    zakaznik: detail.firma,
    kontakt_id: detail.kontakt_id,
    obchodnik_email: detail.obchodnik_email,
    ke_kontrole: podezrela.length > 0,
    podezrela_cisla: podezrela,
  },
}];

